        .put_artifact_sequence(seq)
        .map_err(|e| format!("put failed: {}", e))?;

    assert_eq!(batch.staged_metadata_bytes, 19);
    assert_eq!(batch.staged_event_bytes(), 0);

    drop(batch);
    let raw = journal
        .artifact_acceptance
        .get(LAST_ISSUED_KEY)
