    batch.commit()?;

    let raw = journal
        .artifact_acceptance
        .get(LAST_ISSUED_KEY)
        .map_err(|e| format!("read counter failed: {}", e))?;
    let raw = raw.ok_or("raw counter is None")?;
    assert_eq!(raw.as_ref(), &1u64.to_be_bytes());
    assert_eq!(journal.events_for_run(RunId::new(1))?, vec![event]);
    Ok(())
}

