    assert!(matches!(batch.commit(), Err(JournalError::BatchAborted)));

    let raw = journal
        .artifact_acceptance
        .get(LAST_ISSUED_KEY)
        .map_err(|e| format!("read counter failed: {}", e))?;
    assert!(raw.is_none());
    Ok(())
}

