    assert_eq!(batch.staged_event_bytes(), 0);
    assert!(matches!(batch.commit(), Err(JournalError::BatchAborted)));

    let raw = journal
        .artifact_acceptance
        .get(LAST_ISSUED_KEY)
        .map_err(|e| format!("read counter failed: {}", e))?;
    assert!(raw.is_none());
    Ok(())
}

